import React, { useState, useRef } from "react";
import { 
  X, User, Truck, AlertCircle, BookOpen, 
  Award, AlertTriangle, CheckCircle, Activity 
} from "lucide-react";
import ScheduleTab from "../tabs/ScheduleTab";
import ReportsTab from "../tabs/ReportsTab";
import TrainingTab from "../tabs/TrainingTab";

const WorkerDashboard = () => {
  const [activeTab, setActiveTab] = useState("schedule");
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const scrollRef = useRef(null);

  const tabs = [
    { id: "schedule", label: "Tasks", icon: <Truck size={24} />, color: "#CAD23C" },
    { id: "reports", label: "Issues", icon: <AlertCircle size={24} />, color: "#AB1717" },
    { id: "training", label: "Learn", icon: <BookOpen size={24} />, color: "#A1AED1" },
  ];

  const scrollToTab = (tabId) => {
    const index = tabs.findIndex(t => t.id === tabId);
    setActiveTab(tabId);
    scrollRef.current.scrollTo({ left: index * window.innerWidth, behavior: "smooth" });
  };

  const handleScroll = () => {
    if (scrollRef.current) {
      const index = Math.round(scrollRef.current.scrollLeft / window.innerWidth);
      if (tabs[index] && tabs[index].id !== activeTab) {
        setActiveTab(tabs[index].id);
      }
    }
  };

  return (
    <div className="h-screen bg-[#FDFAD8] font-sans relative overflow-hidden perspective-1000">

      {/* --- PROFILE LAYER (READ-ONLY) --- */}
      <div className={`absolute inset-0 z-[80] transition-all duration-1000 ease-[cubic-bezier(0.23,1,0.32,1)] flex items-center justify-center p-6 md:p-12 ${isProfileOpen ? "opacity-100 scale-100" : "opacity-0 scale-125 pointer-events-none"}`}>
        <div className="w-full h-full bg-[#FDFAD8] rounded-[60px] shadow-2xl relative overflow-hidden flex flex-col border-[12px] border-white">
          <button onClick={() => setIsProfileOpen(false)} className="absolute top-8 right-8 w-14 h-14 bg-white rounded-full flex items-center justify-center text-[#47510B] hover:rotate-90 transition-transform shadow-xl z-50">
            <X size={28} />
          </button>

          <div className="flex-1 overflow-y-auto no-scrollbar p-10 md:p-20">
            {/* PROFILE HEADER */}
            <div className="flex flex-col md:flex-row justify-between items-start gap-12 mb-16">
              <div>
                <h3 className="text-7xl font-black italic text-[#47510B] uppercase tracking-tighter leading-[0.85] mb-4">
                  Marcus<br/><span className="text-[#CAD23C]">Sterling.</span>
                </h3>
                <div className="flex gap-4">
                    <p className="text-xs font-black uppercase tracking-widest text-[#47510B] bg-white px-4 py-2 rounded-xl border-2 border-[#47510B]">ID: 7729_X</p>
                    <p className="text-xs font-black uppercase tracking-widest text-[#47510B] bg-[#CAD23C] px-4 py-2 rounded-xl border-2 border-[#47510B]">Unit_04</p>
                </div>
              </div>

              <div className="flex gap-6">
                <div className="bg-[#CAD23C] p-8 rounded-[40px] border-4 border-[#47510B] shadow-[10px_10px_0_0_#47510B] text-center">
                    <Award size={40} className="text-[#47510B] mx-auto mb-2"/>
                    <p className="text-[10px] font-black opacity-60 uppercase">Badges</p>
                    <p className="text-4xl font-[1000] italic text-[#47510B]">12</p>
                </div>
                <div className="bg-[#AB1717] p-8 rounded-[40px] border-4 border-[#47510B] shadow-[10px_10px_0_0_#47510B] text-center text-white">
                    <AlertTriangle size={40} className="text-[#FDFAD8] mx-auto mb-2"/>
                    <p className="text-[10px] font-black opacity-60 uppercase text-[#FDFAD8]">Penalties</p>
                    <p className="text-4xl font-[1000] italic text-[#FDFAD8]">01</p>
                </div>
              </div>
            </div>

            {/* HISTORY ARCHIVE: TOP 3 HERO + SCROLL */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
              <div className="flex flex-col">
                <h4 className="flex items-center gap-3 text-3xl font-black italic text-[#47510B] uppercase tracking-tighter mb-8 px-2">
                  <Activity size={28} /> Resolved_Issues
                </h4>
                <div className="h-[400px] overflow-y-auto pr-4 space-y-4 custom-scrollbar">
                  {[1, 2, 3, 4, 5, 6].map((i) => (
                    <div key={i} className={`p-6 rounded-[30px] border-4 border-[#47510B] flex items-center justify-between transition-all ${i <= 3 ? 'bg-white shadow-[6px_6px_0_0_#CAD23C]' : 'bg-white/40 border-dashed opacity-60 hover:opacity-100 hover:bg-white'}`}>
                      <div>
                        <p className="text-[10px] font-black opacity-30 italic uppercase mb-1">MAR 1{i} // 2026</p>
                        <p className="font-black text-[#47510B] uppercase text-lg italic">Sector_0{i}_Report</p>
                      </div>
                      <CheckCircle size={24} className="text-[#CAD23C]" />
                    </div>
                  ))}
                </div>
              </div>

              <div className="flex flex-col">
                <h4 className="flex items-center gap-3 text-3xl font-black italic text-[#47510B] uppercase tracking-tighter mb-8 px-2">
                  <Truck size={28} /> Route_History
                </h4>
                <div className="h-[400px] overflow-y-auto pr-4 space-y-4 custom-scrollbar">
                  {[1, 2, 3, 4, 5, 6].map((i) => (
                    <div key={i} className={`p-6 rounded-[30px] border-4 border-[#47510B] flex items-center justify-between transition-all ${i <= 3 ? 'bg-white shadow-[6px_6px_0_0_#FFB6A9]' : 'bg-white/40 border-dashed opacity-60 hover:opacity-100 hover:bg-white'}`}>
                      <div>
                        <p className="text-[10px] font-black opacity-30 italic uppercase mb-1">Mission_Grid_0{i}</p>
                        <p className="font-black text-[#47510B] uppercase text-lg italic leading-tight">Zone_Clear_Verify</p>
                      </div>
                      <span className="text-[10px] font-black bg-[#47510B] text-[#CAD23C] px-3 py-1 rounded-lg">OK</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* --- DASHBOARD LAYER --- */}
      <div className={`h-full w-full transition-all duration-1000 ease-[cubic-bezier(0.23,1,0.32,1)] flex flex-col ${isProfileOpen ? "scale-50 opacity-0 -translate-x-full pointer-events-none" : "scale-100 opacity-100"}`}>
        <header className="fixed top-0 w-full max-w-[1100px] left-1/2 -translate-x-1/2 pt-10 px-8 flex justify-between items-center z-50">
          <h2 className="text-3xl font-black italic text-[#47510B] uppercase tracking-tighter">{activeTab}<span className="text-[#CAD23C]">.</span></h2>
          <button onClick={() => setIsProfileOpen(true)} className="bg-[#47510B] p-1.5 pr-5 rounded-2xl flex items-center gap-3 border-2 border-white shadow-lg text-[#CAD23C] hover:scale-105 transition-all">
            <div className="w-9 h-9 rounded-xl bg-[#CAD23C] flex items-center justify-center text-[#47510B]"><User size={20} strokeWidth={3} /></div>
            <span className="font-black text-[11px] uppercase tracking-[0.2em]">Marcus.7729</span>
          </button>
        </header>

        <main ref={scrollRef} onScroll={handleScroll} className="flex-1 flex overflow-x-auto snap-x snap-mandatory no-scrollbar">
          <section className="min-w-full h-full snap-start flex items-center justify-center px-10">
            <ScheduleTab onNavigateToReports={() => scrollToTab("reports")} />
          </section>
          <section className="min-w-full h-full snap-start flex items-center justify-center px-10">
            <ReportsTab />
          </section>
          <section className="min-w-full h-full snap-start flex items-center justify-center px-10">
            <TrainingTab />
          </section>
        </main>

        <footer className="fixed bottom-12 left-1/2 -translate-x-1/2 z-50">
          <nav className="bg-[#47510B]/90 backdrop-blur-3xl border border-white/20 px-4 py-3.5 rounded-[40px] shadow-2xl flex items-center gap-3">
            {tabs.map((tab) => (
              <button key={tab.id} onClick={() => scrollToTab(tab.id)} className={`flex items-center gap-3 px-8 py-4 rounded-[30px] transition-all duration-500 group ${activeTab === tab.id ? "bg-[#CAD23C] shadow-xl scale-110" : "text-white/40 hover:text-white"}`}>
                <div style={{ color: activeTab === tab.id ? '#47510B' : 'inherit' }}>{tab.icon}</div>
                {activeTab === tab.id && <span className="text-[11px] font-[1000] uppercase tracking-widest text-[#47510B]">{tab.label}</span>}
              </button>
            ))}
          </nav>
        </footer>
      </div>
    </div>
  );
};

export default WorkerDashboard;
